# -*- coding: utf-8 -*-
from un_base import *
unit('w1','web','Trang web và HTML cơ bản',8,
 ['Mô tả được cấu trúc một tài liệu HTML (html, head, body).','Dùng đúng các thẻ văn bản, liên kết, ảnh, âm thanh, video, khung nội tuyến.','Giải thích được trình duyệt dựng một trang web như thế nào.'],
 [sec('Trình duyệt dựng trang web thế nào?',['Gõ địa chỉ web, trình duyệt hỏi máy chủ DNS để đổi tên miền thành địa chỉ IP, rồi gửi yêu cầu HTTP tới máy chủ web. Máy chủ trả về tệp HTML (kèm CSS, ảnh…).','Trình duyệt đọc HTML, dựng cây phần tử, áp CSS rồi vẽ trang lên màn hình.'],key='HTML là ngôn ngữ ĐÁNH DẤU siêu văn bản (không phải ngôn ngữ lập trình): nó mô tả cấu trúc nội dung, không có vòng lặp hay rẽ nhánh.',fig='web_flow'),
  sec('Cấu trúc tài liệu HTML',['Một trang gồm hai phần: head (thông tin về trang: title hiển thị trên tab, link tới CSS, meta mã hoá) và body (nội dung hiển thị).','Thẻ có thể lồng nhau, tạo thành cây. Hầu hết thẻ có cặp mở – đóng (<p>…</p>); một số thẻ rỗng như <img>, <br>.'],fig='html_struct',html=dict(css='h1{color:#0b6e8a} p{margin:6px 0}',body='<h1>Tin học 12</h1><p>Xin <b>chào</b> các em.</p><p>Đây là <i>đoạn thứ hai</i>.</p>')),
  sec('Liên kết, ảnh, âm thanh, video',['<a href="…"> tạo liên kết: href="#muc2" nhảy tới phần tử có id="muc2" trong cùng trang; liên kết ra ngoài website dùng địa chỉ tuyệt đối https://…; target="_blank" mở tab mới.','<img src alt>: alt là văn bản thay thế khi ảnh lỗi và cho trình đọc màn hình. <video> có thêm width, height, poster (ảnh bìa); <audio> không có poster. controls hiện thanh điều khiển; nhiều thẻ <source> cho nhiều định dạng. <iframe> nhúng trang web khác vào một khung.'],key='id phải DUY NHẤT trong trang; class có thể dùng chung cho nhiều phần tử.',code='<a href="#muc2">Tới mục 2</a>\n<h2 id="muc2">Mục 2</h2>\n<img src="logo.png" alt="Logo trường">\n<video controls width="320" poster="bia.jpg">\n  <source src="bai.mp4" type="video/mp4">\n</video>',lang='html')],
 ['html','html-cautruc','html-vanban','html-lienket','html-media'])
unit('w2','web','Bảng, danh sách và biểu mẫu',9,
 ['Viết và đọc được bảng HTML có ô gộp (colspan, rowspan).','Phân biệt id, name, for và các thuộc tính disabled, readonly, required.','Biết khi nào dữ liệu biểu mẫu được gửi đi.'],
 [sec('Bảng và danh sách',['table › tr (hàng) › td (ô dữ liệu) hoặc th (ô tiêu đề); caption là tiêu đề bảng. Danh sách: ul (không thứ tự), ol (có thứ tự), li (mục).'],html=dict(css='table{border-collapse:collapse}td,th{border:1px solid #888;padding:4px 10px}',body='<table><caption>Điểm</caption><tr><th colspan="2">Học kì 1</th></tr><tr><td>Toán</td><td>9</td></tr><tr><td>Tin</td><td>10</td></tr></table>')),
  sec('Kiến thức khó: ô gộp chiếm chỗ',['Muốn đếm đúng số thẻ td, hãy vẽ lưới trước. colspan="2" gộp hai ô nằm ngang; rowspan="2" gộp hai ô xếp dọc.','Ô rowspan ở hàng trên đã chiếm một vị trí của hàng dưới, nên hàng dưới viết ít thẻ td hơn.'],hard=True,fig='html_bang'),
  sec('Biểu mẫu (form)',['label for="u" gắn với ô nhập có id="u": nháy vào nhãn thì con trỏ vào ô. Các nút radio cùng name tạo thành nhóm chỉ chọn một. Dữ liệu gửi đi theo name, không theo id.','required: bắt buộc nhập. readonly: không sửa được nhưng VẪN gửi. disabled: không sửa được và KHÔNG gửi.'],key='id dùng cho CSS/JS/label; name dùng để gửi dữ liệu lên máy chủ.',fig='forms',html=dict(css='label{margin-right:6px} input{margin-right:10px}',body='<form><label for="u">Tên</label><input type="text" id="u" name="user"><br><br><input type="radio" name="g" value="n"> Nam <input type="radio" name="g" value="f"> Nữ</form>'))],
 ['html-bang','html-bieumau','forms'])
unit('w3','web','CSS: nhúng, bộ chọn, kế thừa',9,
 ['Nêu được ba cách nhúng CSS và khi nào dùng cách nào.','Viết đúng bộ chọn: thẻ, lớp, id, thuộc tính, con cháu, con trực tiếp, lớp giả, phần tử giả.','Phân biệt thuộc tính được kế thừa và không được kế thừa.'],
 [sec('Ba cách nhúng CSS',['Thuộc tính style trong từng thẻ; thẻ <style> trong head của trang; tệp .css riêng nhúng bằng <link rel="stylesheet" href="…"> đặt trong head.','Tệp ngoài dùng chung cho nhiều trang: sửa một nơi, cả website đổi.'],key='CSS tách phần trình bày khỏi nội dung HTML.'),
  sec('Bộ chọn',['Thẻ: p; lớp: .a; id: #b; thuộc tính: input[type="text"]; nhiều bộ chọn: h1, h2.','A B: B là con cháu của A (mọi cấp). A > B: B là con TRỰC TIẾP. A + B: B đứng liền sau A. A ~ B: mọi B cùng cấp đứng sau A. .a.b (viết liền): một phần tử có cả hai lớp; .a .b (có dấu cách): .b nằm trong .a.','Lớp giả dùng một dấu hai chấm (a:hover, li:first-child, a:link); phần tử giả dùng hai (p::first-line, p::first-letter).'],key='Đọc bộ chọn từ PHẢI sang TRÁI để biết phần tử nào được chọn.',hard=True,fig='css_tree'),
  sec('Ví dụ có kết quả',['Hãy xem vì sao chỉ đoạn 1 đổi màu: div > p chỉ chọn con trực tiếp, đoạn 2 nằm trong span nên là cháu.'],html=dict(css='div > p{color:#b3261e;font-weight:bold} div p{border-bottom:1px dashed #888}',body='<div><p>Đoạn 1 (con trực tiếp)</p><span><p>Đoạn 2 (cháu)</p></span></div>')),
  sec('Kế thừa',['Thuộc tính liên quan tới chữ (color, font-family, font-size, text-align) được phần tử con kế thừa; thuộc tính khung (border, margin, padding, background) thì không.','Quy tắc ghi đè chỉ thay đúng thuộc tính bị trùng: h1{color:red;text-align:center} rồi h1{text-align:left} cho chữ đỏ, căn trái.'])],
 ['css','css-nhung','css-selector','css-pseudo','css-ke-thua','css-vanban','css-mau'])
unit('w4','web','CSS: mức ưu tiên và trọng số',8,
 ['Sắp xếp được thang ưu tiên của CSS.','Tính được trọng số của một bộ chọn.','Dự đoán đúng quy tắc nào thắng khi nhiều quy tắc cùng áp dụng.'],
 [sec('Thang bậc ưu tiên',['Trình duyệt xét từ trên xuống, gặp tầng nào phân thắng bại thì dừng: !important › style trong thẻ › trọng số bộ chọn › viết sau (khi bằng nhau) › kế thừa › mặc định.'],fig='css_uutien'),
  sec('Tính trọng số',['id = 100, lớp/lớp giả/thuộc tính = 10, tên thẻ/phần tử giả = 1; cộng dồn. Các ký hiệu *, >, +, ~ không có điểm.'],key='Con số cộng dồn: 11 lớp = 110 vẫn lớn hơn 1 id = 100, nhưng 9 lớp = 90 thì thua.',hard=True,fig='css_trongso'),
  sec('Ví dụ có kết quả',['p = 1, .a = 10, #b = 100 nên #b thắng dù viết trước. Nếu thêm .a{color:black !important} thì chữ đen vì !important ở tầng cao nhất.'],html=dict(css='p{color:blue} .a{color:green} #b{color:#b3261e}',body='<p id="b" class="a">Chữ này màu đỏ vì #b = 100 điểm</p>'),code='p  {color:blue}   /* 1   */\n.a {color:green}  /* 10  */\n#b {color:red}    /* 100 → thắng */',lang='css')],
 ['css-uutien','css-specificity'])
unit('w5','web','CSS: mô hình hộp, bố cục, Flexbox',10,
 ['Tính được kích thước thật của hộp (content-box và border-box).','Giải thích được lề dọc gộp nhau.','Dùng được Flexbox, position, đơn vị tương đối và @media.'],
 [sec('Mô hình hộp',['Mỗi phần tử là một hộp, từ trong ra ngoài: content → padding → border → margin. Padding nằm trong viền (có màu nền); margin nằm ngoài viền (trong suốt).','Mặc định (content-box): bề rộng chiếm chỗ = width + 2×padding + 2×border. Ví dụ 300 + 2×20 + 2×5 = 350px. Với box-sizing: border-box thì width đã gồm cả đệm và viền.'],key='Lề dọc của hai khối liền kề GỘP lại, lấy giá trị lớn hơn (40px và 25px → 40px).',hard=True,fig='css_box'),
  sec('Viết tắt padding và margin',['4 giá trị: trên – phải – dưới – trái (theo kim đồng hồ). 2 giá trị: trên/dưới rồi trái/phải. margin: 0 auto trên khối có width cố định thì căn khối ra giữa.'],html=dict(css='.b{width:160px;padding:10px 20px;border:3px solid #0b6e8a;margin:0 auto;background:#d5ecf3}',body='<div class="b">padding: 10px 20px; margin: 0 auto</div>')),
  sec('Flexbox',['Đặt display:flex cho vùng chứa. Trục chính là hướng xếp (row: ngang, column: dọc), trục phụ vuông góc. justify-content căn theo trục CHÍNH, align-items căn theo trục PHỤ. flex-wrap: wrap cho xuống dòng khi hết chỗ.'],hard=True,fig='css_flex',html=dict(css='.m{display:flex;justify-content:space-between;align-items:center;height:70px;border:1px dashed #888}.m span{background:#d5ecf3;padding:8px 14px}',body='<div class="m"><span>1</span><span>2</span><span>3</span></div>')),
  sec('Định vị và đơn vị',['position: relative (dịch so với chỗ gốc), absolute (theo tổ tiên gần nhất có position khác static), fixed (gắn với khung nhìn khi cuộn). em tính theo cỡ chữ của cha, rem theo cỡ chữ gốc html, % theo kích thước cha.','@media (max-width: 600px){…} chỉ áp dụng khi khung nhìn rộng không quá 600px.'])],
 ['css-box','css-khung'])
unit('w6','web','Thiết kế và xuất bản website',6,
 ['Nêu được các bước làm một website.','Biết kiểm tra trước khi xuất bản.','Hiểu vai trò của tệp CSS dùng chung.'],
 [sec('Quy trình xây dựng website',['Xác định mục đích và đối tượng → phác thảo cấu trúc (sơ đồ trang, menu) → thiết kế giao diện → tạo nội dung bằng HTML/CSS (hoặc trình tạo trang như Google Sites) → kiểm tra → xuất bản và bảo trì.'],key='Dùng chung một tệp CSS và cấu trúc đầu trang để giao diện thống nhất, dễ sửa.'),
  sec('Kiểm tra trước khi xuất bản',['Kiểm tra liên kết, chính tả, biểu mẫu, hiển thị trên nhiều trình duyệt và nhiều cỡ màn hình (thiết kế đáp ứng). Trình tạo trang kéo–thả giúp người không biết HTML/CSS vẫn làm được website.'])],
 ['website'])
